"""Compose a single own-date research edition; no cross-date input reads."""
from pathlib import Path
import datetime as dt,gzip,json,re,sys
ROOT=Path(__file__).resolve().parents[1]
D=sys.argv[1]
assert D in ['2025-08-18','2025-08-19','2025-08-20','2025-08-21','2025-08-22']
feed=json.load(gzip.open(ROOT/'feeds'/f'{D}.json.gz','rt'))
card=json.loads((ROOT/'cards'/f'{D}.json').read_text())
assert card['report_date']==D
items=feed['items'];used={}
CUTOFF=dt.datetime.fromisoformat(D).replace(tzinfo=dt.timezone.utc)
BASELINE=re.compile(r'\b(?:PMI|CPI|GDP|PPI|inflation|unemployment|wages?|payroll|industrial output|retail sales|factory activity|bank loans|new loans|yuan loans|interest rate|cash rate|rate decision)\b',re.I)
def admissible(item):
 age=CUTOFF-dt.datetime.fromisoformat(item['published_at'].replace('Z','+00:00'))
 return item['cat']!='monthly' or age<=dt.timedelta(days=7) or bool(BASELINE.search(item['title']))
BAN=re.compile(r'live updates|live blog|as it happened|stock market today|stock price, news, quote and history|sentiment score, message volume|latest press releases and corporate news|\blive:|\b2026\b|retrospect|hindsight|correction',re.I)
quality={'Reuters':9,'Bloomberg':8,'CNBC':8,'Financial Times':8,'The Wall Street Journal':8,'WSJ':8,'Nikkei Asia':8,'AP News':8,'Associated Press':8,'CoinDesk':7,'The Block':7,'Bankier.pl':7,'PAP':7,'Money.pl':7,'Stocktwits':8,'Yahoo Finance':6}
def pick(rx,topic=None,cat=None):
    pat=re.compile(rx,re.I)
    pool=[x for x in items if admissible(x) and pat.search(x['title']) and not BAN.search(x['title']) and (cat is None or x['cat']==cat) and (cat!='result' or not re.search(r'predict|preview|ahead of|set to report|could|estimates? show|expected to|potential|outlook for|forecast|to report',x['title'],re.I))]
    if not pool and cat: return pick(rx,topic,None)
    if not pool: raise ValueError('No eligible source for '+rx)
    def rank(x):
        return (used.get(x['id'],0)==0, -used.get(x['id'],0), (not topic or topic in x.get('topics',[])),quality.get(x['src'],2),x['published_at'])
    x=max(pool,key=rank);used[x['id']]=used.get(x['id'],0)+1;return x

def q(rx,topic=None,cat=None):
    x=pick(rx,topic,cat)
    title=x['title']
    # The final publisher suffix is redundant with inline attribution.
    if title.endswith(' - '+x['src']):title=title[:-len(' - '+x['src'])]
    return x['src']+' reports “'+title+'”. [['+x['id']+']] '

def obs(t,periods=(1,5,20),name=None):
    m=card['markets'][t];n=name or m['name'];text=f"{n} closed at {m['close']}"
    for p in periods:
        c=m[f'chg_{p}s_pct'];w={1:'in the prior session',5:'over five sessions',20:'over 20 sessions'}[p]
        text+=f", {'up' if c>=0 else 'down'} {abs(c):.2f}% {w}"
    return text+f". (Yahoo Finance, prior close {m['session']}) "
def stance(t):
    c=card['markets'][t]['chg_20s_pct'];return 'Bullish' if c>1 else 'Bearish' if c<-1 else 'Mixed'
def part(l,t):return [l,t]
def sourceparts(rows):return [part(l,q(rx,topic,cat)+text) for l,rx,topic,cat,text in rows]

geo=[]
tr=card['treasury'];y=tr['prior_close_pct'];ch=tr['chg_20obs_bps']
rates=(f"The 2Y Treasury yield was {y['2y']} and the 10Y {y['10y']}, with the 10Y−2Y spread at {tr['spread_10y_2y_bps']} bps. "
       f"Over 20 observations the 2Y changed {ch['2y']:+d} bps and the 10Y {ch['10y']:+d} bps; the spread changed {ch['spread']:+d} bps. "
       f"The curve is {tr['curve_shape']}; its move was {tr['curve_move_20obs']}. (US Treasury, prior close {tr['prior_close_date']}) "
       +obs('^GSPC',(20,),'The S&P 500')+obs('^VIX',(1,),'VIX')+obs('DX-Y.NYB',(20,),'DXY')+
       "The portfolio question is whether falling short rates are relieving the financing constraint or discounting weaker demand. The answer comes from credit and earnings confirmation. Do not read a positively sloped curve as an automatic growth endorsement; the level of long-term financing still matters to housing, infrastructure and equity duration.")
geo.append({'key':'US','stance':'Mixed','label':'easing hopes / inflation hurdle','parts':[
part('Macro Stance',q(r'Federal Reserve|\bFed\b|Powell','us_macro')+"The US allocation rests on separating the interest-rate argument from the earnings argument. Easier policy can support the multiple investors pay for a stream of profits; it cannot manufacture that stream if final demand weakens. Maintain exposure to companies that can finance investment internally, while treating expensive businesses dependent on fresh capital as conditional positions. The useful macro signal is the joint behaviour of employment, household spending and inflation, rather than a single reassuring number. A market can tolerate slower nominal growth if costs slow with it, but the margin calculation becomes less forgiving when selling prices soften before wages and financing costs."),
part('Rates & Curve',rates),
part('New / Most Important',q(r'inflation|producer prices|retail sales|consumer spending','us_data')+"That is the pressure point for the next repricing: softer demand and stubborn input costs have different consequences, even when both produce calls for monetary easing. Retailers with purchasing scale can absorb a temporary cost shock differently from suppliers with fixed contracts. Banks benefit from healthy borrowers more reliably than from a steep curve alone. Watch whether equity leadership broadens into profitable domestic businesses while credit remains orderly; a rally concentrated in long-duration stories would offer less reassurance about the underlying demand cycle. Do not confuse a change in the policy conversation with a change in companies' order books."),
part('Playbook ✓',q(r'US stocks|Wall Street|S&P 500|Nasdaq','us_macro')+"Hold a core of cash-generative US equities and add cyclical risk only when improving sales evidence accompanies the financing relief. Use index protection around policy-sensitive exposures rather than abandoning companies with durable cash generation. An adverse inflation surprise would make unprofitable duration the first exposure to cut; deteriorating credit alongside weak employment would shift the hedge toward earnings-sensitive sectors. A benign combination of stable credit, cooler costs and resilient spending would justify broadening beyond the most expensive growth franchises. The trigger is agreement between those channels, not the confidence of a single day's equity move.") ]})
geo.append({'key':'EU','stance':stance('VGK'),'label':'trade exposure / selective value','parts':sourceparts([
('Macro Stance',r'ECB|euro zone|eurozone|European Central Bank','europe',None,"Europe offers a different mix of policy sensitivity and operating leverage. Lower financing costs can help domestic demand, but an exporter still needs customers to place orders and a bank still needs borrowers able to service debt. Prefer balance-sheet strength and domestic revenue visibility where trade uncertainty is difficult to price. The case for adding regional risk improves when household demand and business lending reinforce each other, rather than when a currency move alone flatters reported foreign earnings. Keep country and sector selection explicit: the same macro headline can help a lender and hurt an imported-input manufacturer."),
('Activity & Inflation',r'eurozone|euro zone|Germany|German|European inflation|Europe.*PMI','europe','monthly',"Read the activity mix before declaring a regional recovery. Manufacturing orders, services demand and credit formation do not have to turn together. A better sentiment survey can precede a durable earnings recovery, but it needs confirmation from volumes and margins before supporting a full valuation rerating. Domestic services can offer insulation from the trade channel, whereas capital goods require confidence in overseas demand. The inflation path also matters through real household income: lower prices help purchasing power only if employment remains secure enough for households to spend the benefit."),
('New / Most Important',r'Europe.*tariff|EU.*tariff|European.*trade|Germany.*export|EU.*trade','europe',None,"The transmission runs through pricing, currency translation and the willingness to invest. A negotiated framework can reduce the range of possible outcomes without removing every commercial cost. Companies able to localise production or reprice contracts deserve a different risk allowance from those selling undifferentiated products into a politically sensitive market. Treat a relief rally as an opportunity to improve portfolio quality until orders validate the recovery thesis. The most useful corporate commentary distinguishes what management can control from what depends on another policy announcement."),
('Playbook ✓',r'European stocks|Europe.*stocks|DAX|STOXX|Stoxx','europe',None,"Own selective European financials and industrial franchises where capital returns or order visibility support the valuation; hedge broad exporter exposure if trade friction begins to damage demand. Add regional beta only when stronger activity translates into earnings rather than merely a cheaper discount rate. A renewed squeeze in input costs would argue for pricing power and away from thin-margin manufacturers. An improvement in credit demand alongside stable inflation would justify a wider domestic allocation. Keep the currency risk visible instead of assuming the equity story contains a free foreign-exchange hedge.")])})
geo.append({'key':'CN','stance':stance('ASHR'),'label':'policy support / demand test','parts':sourceparts([
('Macro Stance',r'China.*(?:econom|policy|stimulus)|PBOC|People.s Bank of China','china',None,"China requires separate judgments on liquidity, demand and the equity expression. An easing bias can support financial conditions while private investment remains hesitant; that is why cheaper funding does not automatically become a durable cyclical recovery. Prefer companies with identifiable demand and manageable balance sheets to a broad assumption that policy support lifts every asset. Domestic strategic spending can sustain selected industrial businesses even while household-sensitive sectors struggle. The risk is paying a growth multiple for a policy response whose strongest effect is preventing deterioration. Demand confirmation would make the allocation broader; policy language alone makes it selective."),
('PMIs & Activity',r'China.*PMI|China.*factory|China.*manufactur|China.*industrial|Chinese.*factory','china','monthly',"Activity surveys describe breadth, while production statistics describe output; neither alone settles profitability. Distinguish export orders from domestic orders and large enterprises from smaller private manufacturers. A company can produce more while collecting less cash if prices or payment terms deteriorate. The investment implication is to ask which sectors have volume growth that survives without aggressive discounts. Export resilience is useful but does not establish that household confidence has recovered. The next confirmation should come from new orders, inventories and margins moving in a coherent direction. Until then, index strength can reflect a change in risk appetite more than a turn in the industrial cycle."),
('Credit Impulse',r'China.*(?:bank loans|new loans|yuan loans|lending)|Chinese.*(?:bank loans|new loans|lending)','china','monthly',"Credit supply and credit demand have different implications for asset prices. Banks can have funding available while households remain unwilling to borrow and companies postpone expansion. In that setting, rate relief first lowers the cost of existing obligations; it creates a new growth impulse only when creditworthy borrowers want fresh investment. Watch the composition of lending rather than the headline total, especially the distinction between household mortgages and corporate borrowing. Financing that bridges old liabilities is less powerful for consumption than financing tied to new income-generating activity. The equity opportunity lies where credit becomes revenue, rather than where the funding headline sounds most generous."),
('Property',r'China.*(?:property|housing|home price)|Chinese.*(?:property|housing)|China.*real estate','china','monthly',"Housing is the balance-sheet channel connecting household confidence, local finances and demand for building materials. A slower decline is welcome but differs from a self-sustaining recovery in sales, cash collection and construction. Developers need buyers willing to commit and confidence that projects will be completed; households need confidence in income as well as delivery. Avoid extrapolating a stabilising monthly price statistic into a universal developer recovery. Stronger secondary-market turnover without renewed distress would be a more useful confirmation. For global portfolios, the relevant exposures include construction supply chains and luxury consumption, whose sensitivities to Chinese property wealth can differ substantially."),
('Fiscal, Policy & Trade',r'China.*(?:trade|tariff|fiscal|export|rare earth)|Chinese.*(?:trade|tariff|export)','china',None,"Trade policy can change the destination and timing of orders before changing their ultimate volume. Front-loading, inventory rebuilding and genuine end demand can look similar in a short data window. Companies with flexible production networks may adapt more effectively than suppliers dependent on a narrow destination. Domestic fiscal support can cushion selected sectors, but the durability of that support depends on execution, funding and the willingness of private businesses to follow. Keep strategic industrial investment separate from a broad household reflation thesis. A trade accommodation helps the risk premium; evidence of profitable repeat orders is what would improve the earnings case."),
('Markets & Flows',r'China.*(?:stocks|shares|yuan)|Chinese.*(?:stocks|shares)|Hong Kong.*stocks|Hang Seng','china',None,"The distinction between offshore internet franchises and mainland industrial shares remains central. Their shareholder bases, financing conditions and earnings sensitivities are different, so a regional rally should be tested for breadth before it becomes a global allocation signal. A stronger currency can ease foreign investors' translation concerns while reducing exporters' competitive cushion; neither effect should be treated in isolation. Use the equity instrument that matches the thesis, rather than assuming every China fund provides the same exposure. A durable advance should eventually be supported by business cash generation, because valuation relief without better earnings leaves the position vulnerable to the next policy disappointment."),
('New / Most Important',r'China.*(?:demand|growth|retail|econom)|Chinese.*(?:consumer|econom|growth)','china','monthly',"The decisive question is whether policy and trade relief can reach household and private-sector behaviour. A better market price is useful evidence of willingness to own risk, but it does not settle the direction of underlying spending. Look for corroboration across consumption, new borrowing and corporate profitability before moving from targeted positions to broad cyclical exposure. The upside risk is a reinforcing loop in which confidence improves spending and stronger cash flow improves investment. The downside is an equity rally that discounts that loop before it exists. Position sizing should reflect the distinction between an observable operating improvement and a plausible policy scenario."),
('Playbook ✓',r'China.*(?:stocks|shares|econom)|Hong Kong.*(?:stocks|shares)','china',None,"Hold selective domestic technology and high-quality consumer or internet franchises only where earnings visibility justifies the exposure. Hedge the property-sensitive portion of regional risk until sales and household financing show a more durable turn. Add broader cyclical exposure when stronger orders and credit demand reinforce each other, and cut it if policy support merely rolls existing liabilities forward. The risk budget should recognise currency and overseas-listing exposure as well as the underlying company. ⚠ Divergence: strategic industrial optimism can coexist with weak household balance sheets; a rising technology index is therefore an incomplete test of the domestic recovery thesis.")])})
