# Own-date factual release anchors precede interpretation; omit unavailable vintages.
def maybe_quote(rx,topic=None):
 try:return q(rx,topic)
 except ValueError:return ''
def prepend_geo(key,label,rx,topic=None):
 for g in geo:
  if g['key']==key:
   for p in g['parts']:
    if p[0]==label:p[1]=maybe_quote(rx,topic)+p[1]
