(ROOT/'writer-middle'/f'{D}-base.json').write_text(json.dumps(base,ensure_ascii=False,indent=2))
print(D,'base',sum(len(x.split()) for x in re.findall(r'"((?:[^"\\]|\\.)*)"',json.dumps(base))),'strings words; source selections',len(used))
